struct stringx_buffer { void *data; int ref_count; int length; };
class stringx {
    char *characters;
    stringx_buffer *buffer;
public:
    ~stringx();
    int length() const;
    char &operator[](int index);
    const char *c_str() const;
};
template <class T> void adjustSizes(T &x, T &y);
enum { GT_ButtonSpacing = 20 };
extern stringx ksGlobalButtonArray[21];
class nglTexture;
class Font {
protected:
    struct glyph_info {
        unsigned char ascii;
        unsigned int cell_x, cell_y;
        unsigned int cell_width, cell_height;
        unsigned int glyph_x, glyph_y;
        unsigned int glyph_width, glyph_height;
    };
public:
    bool unset;
    int max_width;
    int getIndex(char c);
    bool CheckArtButtonCodes(const char *text, int &length, int &button_index);
    float getWidth(stringx s, float sc, bool even_number_spacing, float art_button_sc);
protected:
    glyph_info m_chars[256];
    stringx m_texname;
    unsigned int m_texwidth, m_texheight;
    nglTexture *texture;
    int numGlyphs;
    float m_ascent, m_descent;
    float m_scale;
    stringx filename;
    int m_refcount;
    nglTexture *art_button_tex[GT_ButtonSpacing];
    int art_button_width[GT_ButtonSpacing];
    int art_button_height[GT_ButtonSpacing];
};
